25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * AXI4-Stream FIFO
33	 */
34	module axis_fifo #
35	(
36	    // FIFO depth in words
37	    // KEEP_WIDTH words per cycle if KEEP_ENABLE set
38	    // Rounded up to nearest power of 2 cycles
39	    parameter DEPTH = 4096,
40	    // Width of AXI stream interfaces in bits
41	    parameter DATA_WIDTH = 8,
42	    // Propagate tkeep signal
43	    // If disabled, tkeep assumed to be 1'b1
44	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
45	    // tkeep signal width (words per cycle)
46	    parameter KEEP_WIDTH = ((DATA_WIDTH+7)/8),
47	    // Propagate tlast signal
48	    parameter LAST_ENABLE = 1,
49	    // Propagate tid signal
50	    parameter ID_ENABLE = 0,
51	    // tid signal width
52	    parameter ID_WIDTH = 8,
53	    // Propagate tdest signal
54	    parameter DEST_ENABLE = 0,
55	    // tdest signal width
56	    parameter DEST_WIDTH = 8,
57	    // Propagate tuser signal
58	    parameter USER_ENABLE = 1,
59	    // tuser signal width
60	    parameter USER_WIDTH = 1,
61	    // number of RAM pipeline registers
62	    parameter RAM_PIPELINE = 1,
63	    // use output FIFO
64	    // When set, the RAM read enable and pipeline clock enables are removed
65	    parameter OUTPUT_FIFO_ENABLE = 0,
66	    // Frame FIFO mode - operate on frames instead of cycles
67	    // When set, m_axis_tvalid will not be deasserted within a frame
68	    // Requires LAST_ENABLE set
69	    parameter FRAME_FIFO = 0,
70	    // tuser value for bad frame marker
71	    parameter USER_BAD_FRAME_VALUE = 1'b1,
72	    // tuser mask for bad frame marker
73	    parameter USER_BAD_FRAME_MASK = 1'b1,
74	    // Drop frames larger than FIFO
75	    // Requires FRAME_FIFO set
76	    parameter DROP_OVERSIZE_FRAME = FRAME_FIFO,
77	    // Drop frames marked bad
78	    // Requires FRAME_FIFO and DROP_OVERSIZE_FRAME set
79	    parameter DROP_BAD_FRAME = 0,
80	    // Drop incoming frames when full
81	    // When set, s_axis_tready is always asserted
82	    // Requires FRAME_FIFO and DROP_OVERSIZE_FRAME set
83	    parameter DROP_WHEN_FULL = 0,
84	    // Mark incoming frames as bad frames when full
85	    // When set, s_axis_tready is always asserted
86	    // Requires FRAME_FIFO to be clear
87	    parameter MARK_WHEN_FULL = 0,
88	    // Enable pause request input
89	    parameter PAUSE_ENABLE = 0,
90	    // Pause between frames
91	    parameter FRAME_PAUSE = FRAME_FIFO
92	)
93	(
94	    input  wire                   clk,
95	    input  wire                   rst,
96	
97	    /*
98	     * AXI input
99	     */
100	    input  wire [DATA_WIDTH-1:0]  s_axis_tdata,
101	    input  wire [KEEP_WIDTH-1:0]  s_axis_tkeep,
102	    input  wire                   s_axis_tvalid,
103	    output wire                   s_axis_tready,
104	    input  wire                   s_axis_tlast,
105	    input  wire [ID_WIDTH-1:0]    s_axis_tid,
106	    input  wire [DEST_WIDTH-1:0]  s_axis_tdest,
107	    input  wire [USER_WIDTH-1:0]  s_axis_tuser,
108	
109	    /*
110	     * AXI output
111	     */
112	    output wire [DATA_WIDTH-1:0]  m_axis_tdata,
113	    output wire [KEEP_WIDTH-1:0]  m_axis_tkeep,
114	    output wire                   m_axis_tvalid,
115	    input  wire                   m_axis_tready,
116	    output wire                   m_axis_tlast,
117	    output wire [ID_WIDTH-1:0]    m_axis_tid,
118	    output wire [DEST_WIDTH-1:0]  m_axis_tdest,
119	    output wire [USER_WIDTH-1:0]  m_axis_tuser,
120	
121	    /*
122	     * Pause
123	     */
124	    input  wire                   pause_req,
125	    output wire                   pause_ack,
126	
127	    /*
128	     * Status
129	     */
130	    output wire [$clog2(DEPTH):0] status_depth,
131	    output wire [$clog2(DEPTH):0] status_depth_commit,
132	    output wire                   status_overflow,
133	    output wire                   status_bad_frame,
134	    output wire                   status_good_frame
135	);
136	
137	parameter ADDR_WIDTH = (KEEP_ENABLE && KEEP_WIDTH > 1) ? $clog2(DEPTH/KEEP_WIDTH) : $clog2(DEPTH);
138	
139	parameter OUTPUT_FIFO_ADDR_WIDTH = RAM_PIPELINE < 2 ? 3 : $clog2(RAM_PIPELINE*2+7);
140	
141	// check configuration
142	initial begin
143	    if (FRAME_FIFO && !LAST_ENABLE) begin
144	        $error("Error: FRAME_FIFO set requires LAST_ENABLE set (instance %m)");
145	        $finish;
146	    end
147	
148	    if (DROP_OVERSIZE_FRAME && !FRAME_FIFO) begin
149	        $error("Error: DROP_OVERSIZE_FRAME set requires FRAME_FIFO set (instance %m)");
150	        $finish;
151	    end
152	
153	    if (DROP_BAD_FRAME && !(FRAME_FIFO && DROP_OVERSIZE_FRAME)) begin
154	        $error("Error: DROP_BAD_FRAME set requires FRAME_FIFO and DROP_OVERSIZE_FRAME set (instance %m)");
155	        $finish;
156	    end
157	
158	    if (DROP_WHEN_FULL && !(FRAME_FIFO && DROP_OVERSIZE_FRAME)) begin
159	        $error("Error: DROP_WHEN_FULL set requires FRAME_FIFO and DROP_OVERSIZE_FRAME set (instance %m)");
160	        $finish;
161	    end
162	
163	    if ((DROP_BAD_FRAME || MARK_WHEN_FULL) && (USER_BAD_FRAME_MASK & {USER_WIDTH{1'b1}}) == 0) begin
164	        $error("Error: Invalid USER_BAD_FRAME_MASK value (instance %m)");
165	        $finish;
166	    end
167	
168	    if (MARK_WHEN_FULL && FRAME_FIFO) begin
169	        $error("Error: MARK_WHEN_FULL is not compatible with FRAME_FIFO (instance %m)");
170	        $finish;
171	    end
172	
173	    if (MARK_WHEN_FULL && !LAST_ENABLE) begin
174	        $error("Error: MARK_WHEN_FULL set requires LAST_ENABLE set (instance %m)");
175	        $finish;
176	    end
177	end
178	
179	localparam KEEP_OFFSET = DATA_WIDTH;
180	localparam LAST_OFFSET = KEEP_OFFSET + (KEEP_ENABLE ? KEEP_WIDTH : 0);
181	localparam ID_OFFSET   = LAST_OFFSET + (LAST_ENABLE ? 1          : 0);
182	localparam DEST_OFFSET = ID_OFFSET   + (ID_ENABLE   ? ID_WIDTH   : 0);
183	localparam USER_OFFSET = DEST_OFFSET + (DEST_ENABLE ? DEST_WIDTH : 0);
184	localparam WIDTH       = USER_OFFSET + (USER_ENABLE ? USER_WIDTH : 0);
185	
186	reg [ADDR_WIDTH:0] wr_ptr_reg = {ADDR_WIDTH+1{1'b0}};
187	reg [ADDR_WIDTH:0] wr_ptr_commit_reg = {ADDR_WIDTH+1{1'b0}};
188	reg [ADDR_WIDTH:0] rd_ptr_reg = {ADDR_WIDTH+1{1'b0}};
189	
190	(* ramstyle = "no_rw_check" *)
191	reg [WIDTH-1:0] mem[(2**ADDR_WIDTH)-1:0];
192	reg mem_read_data_valid_reg = 1'b0;
193	
194	(* shreg_extract = "no" *)
195	reg [WIDTH-1:0] m_axis_pipe_reg[RAM_PIPELINE+1-1:0];
196	reg [RAM_PIPELINE+1-1:0] m_axis_tvalid_pipe_reg = 0;
197	
198	// full when first MSB different but rest same
199	wire full = wr_ptr_reg == (rd_ptr_reg ^ {1'b1, {ADDR_WIDTH{1'b0}}});
200	// empty when pointers match exactly
201	wire empty = wr_ptr_commit_reg == rd_ptr_reg;
202	// overflow within packet
203	wire full_wr = wr_ptr_reg == (wr_ptr_commit_reg ^ {1'b1, {ADDR_WIDTH{1'b0}}});
204	
205	reg s_frame_reg = 1'b0;
206	
207	reg drop_frame_reg = 1'b0;
208	reg mark_frame_reg = 1'b0;
209	reg send_frame_reg = 1'b0;
210	reg [ADDR_WIDTH:0] depth_reg = 0;
211	reg [ADDR_WIDTH:0] depth_commit_reg = 0;
212	reg overflow_reg = 1'b0;
213	reg bad_frame_reg = 1'b0;
214	reg good_frame_reg = 1'b0;
215	
216	assign s_axis_tready = FRAME_FIFO ? (!full || (full_wr && DROP_OVERSIZE_FRAME) || DROP_WHEN_FULL) : (!full || MARK_WHEN_FULL);
217	
218	wire [WIDTH-1:0] s_axis;
219	
220	generate
221	    assign s_axis[DATA_WIDTH-1:0] = s_axis_tdata;
222	    if (KEEP_ENABLE) assign s_axis[KEEP_OFFSET +: KEEP_WIDTH] = s_axis_tkeep;
223	    if (LAST_ENABLE) assign s_axis[LAST_OFFSET]               = s_axis_tlast | mark_frame_reg;
224	    if (ID_ENABLE)   assign s_axis[ID_OFFSET   +: ID_WIDTH]   = s_axis_tid;
225	    if (DEST_ENABLE) assign s_axis[DEST_OFFSET +: DEST_WIDTH] = s_axis_tdest;
226	    if (USER_ENABLE) assign s_axis[USER_OFFSET +: USER_WIDTH] = mark_frame_reg ? USER_BAD_FRAME_VALUE : s_axis_tuser;
227	endgenerate
228	
229	wire [WIDTH-1:0] m_axis = m_axis_pipe_reg[RAM_PIPELINE+1-1];
230	
231	wire                   m_axis_tready_pipe;
232	wire                   m_axis_tvalid_pipe = m_axis_tvalid_pipe_reg[RAM_PIPELINE+1-1];
233	
234	wire [DATA_WIDTH-1:0]  m_axis_tdata_pipe  = m_axis[DATA_WIDTH-1:0];
235	wire [KEEP_WIDTH-1:0]  m_axis_tkeep_pipe  = KEEP_ENABLE ? m_axis[KEEP_OFFSET +: KEEP_WIDTH] : {KEEP_WIDTH{1'b1}};
236	wire                   m_axis_tlast_pipe  = LAST_ENABLE ? m_axis[LAST_OFFSET] : 1'b1;
237	wire [ID_WIDTH-1:0]    m_axis_tid_pipe    = ID_ENABLE   ? m_axis[ID_OFFSET +: ID_WIDTH] : {ID_WIDTH{1'b0}};
238	wire [DEST_WIDTH-1:0]  m_axis_tdest_pipe  = DEST_ENABLE ? m_axis[DEST_OFFSET +: DEST_WIDTH] : {DEST_WIDTH{1'b0}};
239	wire [USER_WIDTH-1:0]  m_axis_tuser_pipe  = USER_ENABLE ? m_axis[USER_OFFSET +: USER_WIDTH] : {USER_WIDTH{1'b0}};
240	
241	wire                   m_axis_tready_out;
242	wire                   m_axis_tvalid_out;
243	
244	wire [DATA_WIDTH-1:0]  m_axis_tdata_out;
245	wire [KEEP_WIDTH-1:0]  m_axis_tkeep_out;
246	wire                   m_axis_tlast_out;
247	wire [ID_WIDTH-1:0]    m_axis_tid_out;
248	wire [DEST_WIDTH-1:0]  m_axis_tdest_out;
249	wire [USER_WIDTH-1:0]  m_axis_tuser_out;
250	
251	wire pipe_ready;
252	
253	assign status_depth = (KEEP_ENABLE && KEEP_WIDTH > 1) ? {depth_reg, {$clog2(KEEP_WIDTH){1'b0}}} : depth_reg;
254	assign status_depth_commit = (KEEP_ENABLE && KEEP_WIDTH > 1) ? {depth_commit_reg, {$clog2(KEEP_WIDTH){1'b0}}} : depth_commit_reg;
255	assign status_overflow = overflow_reg;
256	assign status_bad_frame = bad_frame_reg;
257	assign status_good_frame = good_frame_reg;
258	
259	// Write logic
260	always @(posedge clk) begin
261	    overflow_reg <= 1'b0;
262	    bad_frame_reg <= 1'b0;
263	    good_frame_reg <= 1'b0;
264	
265	    if (s_axis_tready && s_axis_tvalid && LAST_ENABLE) begin
266	        // track input frame status
267	        s_frame_reg <= !s_axis_tlast;
268	    end
269	
270	    if (FRAME_FIFO) begin
271	        // frame FIFO mode
272	        if (s_axis_tready && s_axis_tvalid) begin
273	            // transfer in
274	            if ((full && DROP_WHEN_FULL) || (full_wr && DROP_OVERSIZE_FRAME) || drop_frame_reg) begin
275	                // full, packet overflow, or currently dropping frame
276	                // drop frame
277	                drop_frame_reg <= 1'b1;
278	                if (s_axis_tlast) begin
279	                    // end of frame, reset write pointer
280	                    wr_ptr_reg <= wr_ptr_commit_reg;
281	                    drop_frame_reg <= 1'b0;
282	                    overflow_reg <= 1'b1;
283	                end
284	            end else begin
285	                // store it
286	                mem[wr_ptr_reg[ADDR_WIDTH-1:0]] <= s_axis;
287	                wr_ptr_reg <= wr_ptr_reg + 1;
288	                if (s_axis_tlast || (!DROP_OVERSIZE_FRAME && (full_wr || send_frame_reg))) begin
289	                    // end of frame or send frame
290	                    send_frame_reg <= !s_axis_tlast;
291	                    if (s_axis_tlast && DROP_BAD_FRAME && USER_BAD_FRAME_MASK & ~(s_axis_tuser ^ USER_BAD_FRAME_VALUE)) begin
292	                        // bad packet, reset write pointer
293	                        wr_ptr_reg <= wr_ptr_commit_reg;
294	                        bad_frame_reg <= 1'b1;
295	                    end else begin
296	                        // good packet or packet overflow, update write pointer
297	                        wr_ptr_commit_reg <= wr_ptr_reg + 1;
298	                        good_frame_reg <= s_axis_tlast;
299	                    end
300	                end
301	            end
302	        end else if (s_axis_tvalid && full_wr && !DROP_OVERSIZE_FRAME) begin
303	            // data valid with packet overflow
304	            // update write pointer
305	            send_frame_reg <= 1'b1;
306	            wr_ptr_commit_reg <= wr_ptr_reg;
307	        end
308	    end else begin
309	        // normal FIFO mode
310	        if (s_axis_tready && s_axis_tvalid) begin
311	            if (drop_frame_reg && MARK_WHEN_FULL) begin
312	                // currently dropping frame
313	                if (s_axis_tlast) begin
314	                    // end of frame
315	                    if (!full && mark_frame_reg) begin
316	                        // terminate marked frame
317	                        mark_frame_reg <= 1'b0;
318	                        mem[wr_ptr_reg[ADDR_WIDTH-1:0]] <= s_axis;
319	                        wr_ptr_reg <= wr_ptr_reg + 1;
320	                        wr_ptr_commit_reg <= wr_ptr_reg + 1;
321	                    end
322	                    // end of frame, clear drop flag
323	                    drop_frame_reg <= 1'b0;
324	                    overflow_reg <= 1'b1;
325	                end
326	            end else if ((full || mark_frame_reg) && MARK_WHEN_FULL) begin
327	                // full or marking frame
328	                // drop frame; mark if this isn't the first cycle
329	                drop_frame_reg <= 1'b1;
330	                mark_frame_reg <= mark_frame_reg || s_frame_reg;
331	                if (s_axis_tlast) begin
332	                    drop_frame_reg <= 1'b0;
333	                    overflow_reg <= 1'b1;
334	                end
335	            end else begin
336	                // transfer in
337	                mem[wr_ptr_reg[ADDR_WIDTH-1:0]] <= s_axis;
338	                wr_ptr_reg <= wr_ptr_reg + 1;
339	                wr_ptr_commit_reg <= wr_ptr_reg + 1;
340	            end
341	        end else if ((!full && !drop_frame_reg && mark_frame_reg) && MARK_WHEN_FULL) begin
342	            // terminate marked frame
343	            mark_frame_reg <= 1'b0;
344	            mem[wr_ptr_reg[ADDR_WIDTH-1:0]] <= s_axis;
345	            wr_ptr_reg <= wr_ptr_reg + 1;
346	            wr_ptr_commit_reg <= wr_ptr_reg + 1;
347	        end
348	    end
349	
350	    if (rst) begin
351	        wr_ptr_reg <= {ADDR_WIDTH+1{1'b0}};
352	        wr_ptr_commit_reg <= {ADDR_WIDTH+1{1'b0}};
353	
354	        s_frame_reg <= 1'b0;
355	
356	        drop_frame_reg <= 1'b0;
357	        mark_frame_reg <= 1'b0;
358	        send_frame_reg <= 1'b0;
359	        overflow_reg <= 1'b0;
360	        bad_frame_reg <= 1'b0;
361	        good_frame_reg <= 1'b0;
362	    end
363	end
364	
365	// Status
366	always @(posedge clk) begin
367	    depth_reg <= wr_ptr_reg - rd_ptr_reg;
368	    depth_commit_reg <= wr_ptr_commit_reg - rd_ptr_reg;
369	end
370	
371	// Read logic
372	integer j;
373	
374	always @(posedge clk) begin
375	    if (m_axis_tready_pipe) begin
376	        // output ready; invalidate stage
377	        m_axis_tvalid_pipe_reg[RAM_PIPELINE+1-1] <= 1'b0;
378	    end
379	
380	    for (j = RAM_PIPELINE+1-1; j > 0; j = j - 1) begin
381	        if (m_axis_tready_pipe || ((~m_axis_tvalid_pipe_reg) >> j)) begin
382	            // output ready or bubble in pipeline; transfer down pipeline
383	            m_axis_tvalid_pipe_reg[j] <= m_axis_tvalid_pipe_reg[j-1];
384	            m_axis_pipe_reg[j] <= m_axis_pipe_reg[j-1];
385	            m_axis_tvalid_pipe_reg[j-1] <= 1'b0;
386	        end
387	    end
388	
389	    if (m_axis_tready_pipe || ~m_axis_tvalid_pipe_reg) begin
390	        // output ready or bubble in pipeline; read new data from FIFO
391	        m_axis_tvalid_pipe_reg[0] <= 1'b0;
392	        m_axis_pipe_reg[0] <= mem[rd_ptr_reg[ADDR_WIDTH-1:0]];
393	        if (!empty && pipe_ready) begin
394	            // not empty, increment pointer
395	            m_axis_tvalid_pipe_reg[0] <= 1'b1;
396	            rd_ptr_reg <= rd_ptr_reg + 1;
397	        end
398	    end
399	
400	    if (rst) begin
401	        rd_ptr_reg <= {ADDR_WIDTH+1{1'b0}};
402	        m_axis_tvalid_pipe_reg <= 0;
403	    end
404	end
405	
406	generate
407	
408	if (!OUTPUT_FIFO_ENABLE) begin
409	
410	    assign pipe_ready = 1'b1;
411	
412	    assign m_axis_tready_pipe = m_axis_tready_out;
413	    assign m_axis_tvalid_out = m_axis_tvalid_pipe;
414	
415	    assign m_axis_tdata_out = m_axis_tdata_pipe;
416	    assign m_axis_tkeep_out = m_axis_tkeep_pipe;
417	    assign m_axis_tlast_out = m_axis_tlast_pipe;
418	    assign m_axis_tid_out   = m_axis_tid_pipe;
419	    assign m_axis_tdest_out = m_axis_tdest_pipe;
420	    assign m_axis_tuser_out = m_axis_tuser_pipe;
421	
422	end else begin : output_fifo
423	
424	    // output datapath logic
425	    reg [DATA_WIDTH-1:0] m_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
426	    reg [KEEP_WIDTH-1:0] m_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
427	    reg                  m_axis_tvalid_reg = 1'b0;
428	    reg                  m_axis_tlast_reg  = 1'b0;
429	    reg [ID_WIDTH-1:0]   m_axis_tid_reg    = {ID_WIDTH{1'b0}};
430	    reg [DEST_WIDTH-1:0] m_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
431	    reg [USER_WIDTH-1:0] m_axis_tuser_reg  = {USER_WIDTH{1'b0}};
432	
433	    reg [OUTPUT_FIFO_ADDR_WIDTH+1-1:0] out_fifo_wr_ptr_reg = 0;
434	    reg [OUTPUT_FIFO_ADDR_WIDTH+1-1:0] out_fifo_rd_ptr_reg = 0;
435	    reg out_fifo_half_full_reg = 1'b0;
436	
437	    wire out_fifo_full = out_fifo_wr_ptr_reg == (out_fifo_rd_ptr_reg ^ {1'b1, {OUTPUT_FIFO_ADDR_WIDTH{1'b0}}});
438	    wire out_fifo_empty = out_fifo_wr_ptr_reg == out_fifo_rd_ptr_reg;
439	
440	    (* ram_style = "distributed", ramstyle = "no_rw_check, mlab" *)
441	    reg [DATA_WIDTH-1:0] out_fifo_tdata[2**OUTPUT_FIFO_ADDR_WIDTH-1:0];
442	    (* ram_style = "distributed", ramstyle = "no_rw_check, mlab" *)
443	    reg [KEEP_WIDTH-1:0] out_fifo_tkeep[2**OUTPUT_FIFO_ADDR_WIDTH-1:0];
444	    (* ram_style = "distributed", ramstyle = "no_rw_check, mlab" *)
445	    reg                  out_fifo_tlast[2**OUTPUT_FIFO_ADDR_WIDTH-1:0];
446	    (* ram_style = "distributed", ramstyle = "no_rw_check, mlab" *)
447	    reg [ID_WIDTH-1:0]   out_fifo_tid[2**OUTPUT_FIFO_ADDR_WIDTH-1:0];
448	    (* ram_style = "distributed", ramstyle = "no_rw_check, mlab" *)
449	    reg [DEST_WIDTH-1:0] out_fifo_tdest[2**OUTPUT_FIFO_ADDR_WIDTH-1:0];
450	    (* ram_style = "distributed", ramstyle = "no_rw_check, mlab" *)
451	    reg [USER_WIDTH-1:0] out_fifo_tuser[2**OUTPUT_FIFO_ADDR_WIDTH-1:0];
452	
453	    assign pipe_ready = !out_fifo_half_full_reg;
454	
455	    assign m_axis_tready_pipe = 1'b1;
456	
457	    assign m_axis_tdata_out  = m_axis_tdata_reg;
458	    assign m_axis_tkeep_out  = KEEP_ENABLE ? m_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
459	    assign m_axis_tvalid_out = m_axis_tvalid_reg;
460	    assign m_axis_tlast_out  = LAST_ENABLE ? m_axis_tlast_reg : 1'b1;
461	    assign m_axis_tid_out    = ID_ENABLE   ? m_axis_tid_reg   : {ID_WIDTH{1'b0}};
462	    assign m_axis_tdest_out  = DEST_ENABLE ? m_axis_tdest_reg : {DEST_WIDTH{1'b0}};
463	    assign m_axis_tuser_out  = USER_ENABLE ? m_axis_tuser_reg : {USER_WIDTH{1'b0}};
464	
465	    always @(posedge clk) begin
466	        m_axis_tvalid_reg <= m_axis_tvalid_reg && !m_axis_tready_out;
467	
468	        out_fifo_half_full_reg <= $unsigned(out_fifo_wr_ptr_reg - out_fifo_rd_ptr_reg) >= 2**(OUTPUT_FIFO_ADDR_WIDTH-1);
469	
470	        if (!out_fifo_full && m_axis_tvalid_pipe) begin
471	            out_fifo_tdata[out_fifo_wr_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]] <= m_axis_tdata_pipe;
472	            out_fifo_tkeep[out_fifo_wr_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]] <= m_axis_tkeep_pipe;
473	            out_fifo_tlast[out_fifo_wr_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]] <= m_axis_tlast_pipe;
474	            out_fifo_tid[out_fifo_wr_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]] <= m_axis_tid_pipe;
475	            out_fifo_tdest[out_fifo_wr_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]] <= m_axis_tdest_pipe;
476	            out_fifo_tuser[out_fifo_wr_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]] <= m_axis_tuser_pipe;
477	            out_fifo_wr_ptr_reg <= out_fifo_wr_ptr_reg + 1;
478	        end
479	
480	        if (!out_fifo_empty && (!m_axis_tvalid_reg || m_axis_tready_out)) begin
481	            m_axis_tdata_reg <= out_fifo_tdata[out_fifo_rd_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]];
482	            m_axis_tkeep_reg <= out_fifo_tkeep[out_fifo_rd_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]];
483	            m_axis_tvalid_reg <= 1'b1;
484	            m_axis_tlast_reg <= out_fifo_tlast[out_fifo_rd_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]];
485	            m_axis_tid_reg <= out_fifo_tid[out_fifo_rd_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]];
486	            m_axis_tdest_reg <= out_fifo_tdest[out_fifo_rd_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]];
487	            m_axis_tuser_reg <= out_fifo_tuser[out_fifo_rd_ptr_reg[OUTPUT_FIFO_ADDR_WIDTH-1:0]];
488	            out_fifo_rd_ptr_reg <= out_fifo_rd_ptr_reg + 1;
489	        end
490	
491	        if (rst) begin
492	            out_fifo_wr_ptr_reg <= 0;
493	            out_fifo_rd_ptr_reg <= 0;
494	            m_axis_tvalid_reg <= 1'b0;
495	        end
496	    end
497	
498	end
499	
500	if (PAUSE_ENABLE) begin : pause
501	
502	    // Pause logic
503	    reg pause_reg = 1'b0;
504	    reg pause_frame_reg = 1'b0;
505	
506	    assign m_axis_tready_out = m_axis_tready && !pause_reg;
507	    assign m_axis_tvalid = m_axis_tvalid_out && !pause_reg;
508	
509	    assign m_axis_tdata = m_axis_tdata_out;
510	    assign m_axis_tkeep = m_axis_tkeep_out;
511	    assign m_axis_tlast = m_axis_tlast_out;
512	    assign m_axis_tid   = m_axis_tid_out;
513	    assign m_axis_tdest = m_axis_tdest_out;
514	    assign m_axis_tuser = m_axis_tuser_out;
515	
516	    assign pause_ack = pause_reg;
517	
518	    always @(posedge clk) begin
519	        if (FRAME_PAUSE) begin
520	            if (pause_reg) begin
521	                // paused; update pause status
522	                pause_reg <= pause_req;
523	            end else if (m_axis_tvalid_out) begin
524	                // frame transfer; set frame bit
525	                pause_frame_reg <= 1'b1;
526	                if (m_axis_tready && m_axis_tlast) begin
527	                    // end of frame; clear frame bit and update pause status
528	                    pause_frame_reg <= 1'b0;
529	                    pause_reg <= pause_req;
530	                end
531	            end else if (!pause_frame_reg) begin
532	                // idle; update pause status
533	                pause_reg <= pause_req;
534	            end
535	        end else begin
536	            pause_reg <= pause_req;
537	        end
538	
539	        if (rst) begin
540	            pause_frame_reg <= 1'b0;
541	            pause_reg <= 1'b0;
542	        end
543	    end
544	
545	end else begin
546	
547	    assign m_axis_tready_out = m_axis_tready;
548	    assign m_axis_tvalid = m_axis_tvalid_out;
549	
550	    assign m_axis_tdata = m_axis_tdata_out;
551	    assign m_axis_tkeep = m_axis_tkeep_out;
552	    assign m_axis_tlast = m_axis_tlast_out;
553	    assign m_axis_tid   = m_axis_tid_out;
554	    assign m_axis_tdest = m_axis_tdest_out;
555	    assign m_axis_tuser = m_axis_tuser_out;
556	
557	    assign pause_ack = 1'b0;
558	
559	end
560	
561	endgenerate
562	
563	endmodule
564	
565	`resetall
566

