31	/*
32	 * AXI4-Stream asynchronous FIFO
33	 */
34	module axis_async_fifo #
35	(
36	    // FIFO depth in words
37	    // KEEP_WIDTH words per cycle if KEEP_ENABLE set
38	    // Rounded up to nearest power of 2 cycles
39	    parameter DEPTH = 4096,
40	    // Width of AXI stream interfaces in bits
41	    parameter DATA_WIDTH = 8,
42	    // Propagate tkeep signal
43	    // If disabled, tkeep assumed to be 1'b1
44	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
45	    // tkeep signal width (words per cycle)
46	    parameter KEEP_WIDTH = ((DATA_WIDTH+7)/8),
47	    // Propagate tlast signal
48	    parameter LAST_ENABLE = 1,
49	    // Propagate tid signal
50	    parameter ID_ENABLE = 0,
51	    // tid signal width
52	    parameter ID_WIDTH = 8,
53	    // Propagate tdest signal
54	    parameter DEST_ENABLE = 0,
55	    // tdest signal width
56	    parameter DEST_WIDTH = 8,
57	    // Propagate tuser signal
58	    parameter USER_ENABLE = 1,
59	    // tuser signal width
60	    parameter USER_WIDTH = 1,
61	    // number of RAM pipeline registers
62	    parameter RAM_PIPELINE = 1,
63	    // use output FIFO
64	    // When set, the RAM read enable and pipeline clock enables are removed
65	    parameter OUTPUT_FIFO_ENABLE = 0,
66	    // Frame FIFO mode - operate on frames instead of cycles
67	    // When set, m_axis_tvalid will not be deasserted within a frame
68	    // Requires LAST_ENABLE set
69	    parameter FRAME_FIFO = 0,
70	    // tuser value for bad frame marker
71	    parameter USER_BAD_FRAME_VALUE = 1'b1,
72	    // tuser mask for bad frame marker
73	    parameter USER_BAD_FRAME_MASK = 1'b1,
74	    // Drop frames larger than FIFO
75	    // Requires FRAME_FIFO set
76	    parameter DROP_OVERSIZE_FRAME = FRAME_FIFO,
77	    // Drop frames marked bad
78	    // Requires FRAME_FIFO and DROP_OVERSIZE_FRAME set
79	    parameter DROP_BAD_FRAME = 0,
80	    // Drop incoming frames when full
81	    // When set, s_axis_tready is always asserted
82	    // Requires FRAME_FIFO and DROP_OVERSIZE_FRAME set
83	    parameter DROP_WHEN_FULL = 0,
84	    // Mark incoming frames as bad frames when full
85	    // When set, s_axis_tready is always asserted
86	    // Requires FRAME_FIFO to be clear
87	    parameter MARK_WHEN_FULL = 0,
88	    // Enable pause request input
89	    parameter PAUSE_ENABLE = 0,
90	    // Pause between frames
91	    parameter FRAME_PAUSE = FRAME_FIFO
92	)
93	(
94	    /*
95	     * AXI input
96	     */
97	    input  wire                   s_clk,
98	    input  wire                   s_rst,
99	    input  wire [DATA_WIDTH-1:0]  s_axis_tdata,
100	    input  wire [KEEP_WIDTH-1:0]  s_axis_tkeep,
101	    input  wire                   s_axis_tvalid,
102	    output wire                   s_axis_tready,
103	    input  wire                   s_axis_tlast,
104	    input  wire [ID_WIDTH-1:0]    s_axis_tid,
105	    input  wire [DEST_WIDTH-1:0]  s_axis_tdest,
106	    input  wire [USER_WIDTH-1:0]  s_axis_tuser,
107	
108	    /*
109	     * AXI output
110	     */
111	    input  wire                   m_clk,
112	    input  wire                   m_rst,
113	    output wire [DATA_WIDTH-1:0]  m_axis_tdata,
114	    output wire [KEEP_WIDTH-1:0]  m_axis_tkeep,
115	    output wire                   m_axis_tvalid,
116	    input  wire                   m_axis_tready,
117	    output wire                   m_axis_tlast,
118	    output wire [ID_WIDTH-1:0]    m_axis_tid,
119	    output wire [DEST_WIDTH-1:0]  m_axis_tdest,
120	    output wire [USER_WIDTH-1:0]  m_axis_tuser,
121	
122	    /*
123	     * Pause
124	     */
125	    input  wire                   s_pause_req,
126	    output wire                   s_pause_ack,
127	    input  wire                   m_pause_req,
128	    output wire                   m_pause_ack,
129	
130	    /*
131	     * Status
132	     */
133	    output wire [$clog2(DEPTH):0] s_status_depth,
134	    output wire [$clog2(DEPTH):0] s_status_depth_commit,
135	    output wire                   s_status_overflow,
136	    output wire                   s_status_bad_frame,
137	    output wire                   s_status_good_frame,
138	    output wire [$clog2(DEPTH):0] m_status_depth,
139	    output wire [$clog2(DEPTH):0] m_status_depth_commit,
140	    output wire                   m_status_overflow,
141	    output wire                   m_status_bad_frame,
142	    output wire                   m_status_good_frame
143	);
144	
145	parameter ADDR_WIDTH = (KEEP_ENABLE && KEEP_WIDTH > 1) ? $clog2(DEPTH/KEEP_WIDTH) : $clog2(DEPTH);
146	
147	parameter OUTPUT_FIFO_ADDR_WIDTH = RAM_PIPELINE < 2 ? 3 : $clog2(RAM_PIPELINE*2+7);
148	
149	// check configuration
150	initial begin
151	    if (FRAME_FIFO && !LAST_ENABLE) begin
152	        $error("Error: FRAME_FIFO set requires LAST_ENABLE set (instance %m)");
153	        $finish;
154	    end
155	
156	    if (DROP_OVERSIZE_FRAME && !FRAME_FIFO) begin
157	        $error("Error: DROP_OVERSIZE_FRAME set requires FRAME_FIFO set (instance %m)");
158	        $finish;
159	    end
160	
161	    if (DROP_BAD_FRAME && !(FRAME_FIFO && DROP_OVERSIZE_FRAME)) begin
162	        $error("Error: DROP_BAD_FRAME set requires FRAME_FIFO and DROP_OVERSIZE_FRAME set (instance %m)");
163	        $finish;
164	    end
165	
166	    if (DROP_WHEN_FULL && !(FRAME_FIFO && DROP_OVERSIZE_FRAME)) begin
167	        $error("Error: DROP_WHEN_FULL set requires FRAME_FIFO and DROP_OVERSIZE_FRAME set (instance %m)");
168	        $finish;
169	    end
170	
171	    if ((DROP_BAD_FRAME || MARK_WHEN_FULL) && (USER_BAD_FRAME_MASK & {USER_WIDTH{1'b1}}) == 0) begin
172	        $error("Error: Invalid USER_BAD_FRAME_MASK value (instance %m)");
173	        $finish;
174	    end
175	
176	    if (MARK_WHEN_FULL && FRAME_FIFO) begin
177	        $error("Error: MARK_WHEN_FULL is not compatible with FRAME_FIFO (instance %m)");
178	        $finish;
179	    end
180	
181	    if (MARK_WHEN_FULL && !LAST_ENABLE) begin
182	        $error("Error: MARK_WHEN_FULL set requires LAST_ENABLE set (instance %m)");
183	        $finish;
184	    end
185	end
186	
187	localparam KEEP_OFFSET = DATA_WIDTH;
188	localparam LAST_OFFSET = KEEP_OFFSET + (KEEP_ENABLE ? KEEP_WIDTH : 0);
189	localparam ID_OFFSET   = LAST_OFFSET + (LAST_ENABLE ? 1          : 0);
190	localparam DEST_OFFSET = ID_OFFSET   + (ID_ENABLE   ? ID_WIDTH   : 0);
191	localparam USER_OFFSET = DEST_OFFSET + (DEST_ENABLE ? DEST_WIDTH : 0);
192	localparam WIDTH       = USER_OFFSET + (USER_ENABLE ? USER_WIDTH : 0);
193	
194	function [ADDR_WIDTH:0] bin2gray(input [ADDR_WIDTH:0] b);
195	    bin2gray = b ^ (b >> 1);
196	endfunction
197	
198	function [ADDR_WIDTH:0] gray2bin(input [ADDR_WIDTH:0] g);
199	    integer i;
200	    for (i = 0; i <= ADDR_WIDTH; i = i + 1) begin
201	        gray2bin[i] = ^(g >> i);
202	    end
203	endfunction
204	
205	reg [ADDR_WIDTH:0] wr_ptr_reg = {ADDR_WIDTH+1{1'b0}};
206	reg [ADDR_WIDTH:0] wr_ptr_commit_reg = {ADDR_WIDTH+1{1'b0}};
207	reg [ADDR_WIDTH:0] wr_ptr_gray_reg = {ADDR_WIDTH+1{1'b0}};
208	reg [ADDR_WIDTH:0] wr_ptr_sync_commit_reg = {ADDR_WIDTH+1{1'b0}};
209	reg [ADDR_WIDTH:0] rd_ptr_reg = {ADDR_WIDTH+1{1'b0}};
210	reg [ADDR_WIDTH:0] rd_ptr_gray_reg = {ADDR_WIDTH+1{1'b0}};
211	reg [ADDR_WIDTH:0] wr_ptr_conv_reg = {ADDR_WIDTH+1{1'b0}};
212	reg [ADDR_WIDTH:0] rd_ptr_conv_reg = {ADDR_WIDTH+1{1'b0}};
213	
214	reg [ADDR_WIDTH:0] wr_ptr_temp;
215	reg [ADDR_WIDTH:0] rd_ptr_temp;
216	
217	(* SHREG_EXTRACT = "NO" *)
218	reg [ADDR_WIDTH:0] wr_ptr_gray_sync1_reg = {ADDR_WIDTH+1{1'b0}};
219	(* SHREG_EXTRACT = "NO" *)
220	reg [ADDR_WIDTH:0] wr_ptr_gray_sync2_reg = {ADDR_WIDTH+1{1'b0}};
221	(* SHREG_EXTRACT = "NO" *)
222	reg [ADDR_WIDTH:0] wr_ptr_commit_sync_reg = {ADDR_WIDTH+1{1'b0}};
223	(* SHREG_EXTRACT = "NO" *)
224	reg [ADDR_WIDTH:0] rd_ptr_gray_sync1_reg = {ADDR_WIDTH+1{1'b0}};
225	(* SHREG_EXTRACT = "NO" *)
226	reg [ADDR_WIDTH:0] rd_ptr_gray_sync2_reg = {ADDR_WIDTH+1{1'b0}};
227	
228	reg wr_ptr_update_valid_reg = 1'b0;
229	reg wr_ptr_update_reg = 1'b0;
230	(* SHREG_EXTRACT = "NO" *)
231	reg wr_ptr_update_sync1_reg = 1'b0;
232	(* SHREG_EXTRACT = "NO" *)
233	reg wr_ptr_update_sync2_reg = 1'b0;
234	(* SHREG_EXTRACT = "NO" *)
235	reg wr_ptr_update_sync3_reg = 1'b0;
236	(* SHREG_EXTRACT = "NO" *)
237	reg wr_ptr_update_ack_sync1_reg = 1'b0;
238	(* SHREG_EXTRACT = "NO" *)
239	reg wr_ptr_update_ack_sync2_reg = 1'b0;
240	
241	(* SHREG_EXTRACT = "NO" *)
242	reg s_rst_sync1_reg = 1'b1;
243	(* SHREG_EXTRACT = "NO" *)
244	reg s_rst_sync2_reg = 1'b1;
245	(* SHREG_EXTRACT = "NO" *)
246	reg s_rst_sync3_reg = 1'b1;
247	(* SHREG_EXTRACT = "NO" *)
248	reg m_rst_sync1_reg = 1'b1;
249	(* SHREG_EXTRACT = "NO" *)
250	reg m_rst_sync2_reg = 1'b1;
251	(* SHREG_EXTRACT = "NO" *)
252	reg m_rst_sync3_reg = 1'b1;
253	
254	(* ramstyle = "no_rw_check" *)
255	reg [WIDTH-1:0] mem[(2**ADDR_WIDTH)-1:0];
256	reg mem_read_data_valid_reg = 1'b0;
257	
258	(* shreg_extract = "no" *)
259	reg [WIDTH-1:0] m_axis_pipe_reg[RAM_PIPELINE+1-1:0];
260	reg [RAM_PIPELINE+1-1:0] m_axis_tvalid_pipe_reg = 0;
261	
262	// full when first TWO MSBs do NOT match, but rest matches
263	// (gray code equivalent of first MSB different but rest same)
264	wire full = wr_ptr_gray_reg == (rd_ptr_gray_sync2_reg ^ {2'b11, {ADDR_WIDTH-1{1'b0}}});
265	// empty when pointers match exactly
266	wire empty = FRAME_FIFO ? (rd_ptr_reg == wr_ptr_commit_sync_reg) : (rd_ptr_gray_reg == wr_ptr_gray_sync2_reg);
267	// overflow within packet
268	wire full_wr = wr_ptr_reg == (wr_ptr_commit_reg ^ {1'b1, {ADDR_WIDTH{1'b0}}});
269	
270	// control signals
271	reg write;
272	reg read;
273	reg store_output;
274	
275	reg s_frame_reg = 1'b0;
276	reg m_frame_reg = 1'b0;
277	
278	reg drop_frame_reg = 1'b0;
279	reg mark_frame_reg = 1'b0;
280	reg send_frame_reg = 1'b0;
281	reg overflow_reg = 1'b0;
282	reg bad_frame_reg = 1'b0;
283	reg good_frame_reg = 1'b0;
284	
285	reg m_drop_frame_reg = 1'b0;
286	reg m_terminate_frame_reg = 1'b0;
287	
288	reg [ADDR_WIDTH:0] s_depth_reg = 0;
289	reg [ADDR_WIDTH:0] s_depth_commit_reg = 0;
290	reg [ADDR_WIDTH:0] m_depth_reg = 0;
291	reg [ADDR_WIDTH:0] m_depth_commit_reg = 0;
292	
293	reg overflow_sync1_reg = 1'b0;
294	reg overflow_sync2_reg = 1'b0;
295	reg overflow_sync3_reg = 1'b0;
296	reg overflow_sync4_reg = 1'b0;
297	reg bad_frame_sync1_reg = 1'b0;
298	reg bad_frame_sync2_reg = 1'b0;
299	reg bad_frame_sync3_reg = 1'b0;
300	reg bad_frame_sync4_reg = 1'b0;
301	reg good_frame_sync1_reg = 1'b0;
302	reg good_frame_sync2_reg = 1'b0;
303	reg good_frame_sync3_reg = 1'b0;
304	reg good_frame_sync4_reg = 1'b0;
305	
306	assign s_axis_tready = (FRAME_FIFO ? (!full || (full_wr && DROP_OVERSIZE_FRAME) || DROP_WHEN_FULL) : (!full || MARK_WHEN_FULL)) && !s_rst_sync3_reg;
307	
308	wire [WIDTH-1:0] s_axis;
309	
310	generate
311	    assign s_axis[DATA_WIDTH-1:0] = s_axis_tdata;
312	    if (KEEP_ENABLE) assign s_axis[KEEP_OFFSET +: KEEP_WIDTH] = s_axis_tkeep;
313	    if (LAST_ENABLE) assign s_axis[LAST_OFFSET]               = s_axis_tlast | mark_frame_reg;
314	    if (ID_ENABLE)   assign s_axis[ID_OFFSET   +: ID_WIDTH]   = s_axis_tid;
315	    if (DEST_ENABLE) assign s_axis[DEST_OFFSET +: DEST_WIDTH] = s_axis_tdest;
316	    if (USER_ENABLE) assign s_axis[USER_OFFSET +: USER_WIDTH] = mark_frame_reg ? USER_BAD_FRAME_VALUE : s_axis_tuser;
317	endgenerate
318	
319	wire [WIDTH-1:0] m_axis = m_axis_pipe_reg[RAM_PIPELINE+1-1];
320	
321	wire                   m_axis_tready_pipe;
322	wire                   m_axis_tvalid_pipe = m_axis_tvalid_pipe_reg[RAM_PIPELINE+1-1];
323	
324	wire [DATA_WIDTH-1:0]  m_axis_tdata_pipe  = m_axis[DATA_WIDTH-1:0];
325	wire [KEEP_WIDTH-1:0]  m_axis_tkeep_pipe  = KEEP_ENABLE ? m_axis[KEEP_OFFSET +: KEEP_WIDTH] : {KEEP_WIDTH{1'b1}};
326	wire                   m_axis_tlast_pipe  = LAST_ENABLE ? m_axis[LAST_OFFSET] | m_terminate_frame_reg : 1'b1;
327	wire [ID_WIDTH-1:0]    m_axis_tid_pipe    = ID_ENABLE   ? m_axis[ID_OFFSET +: ID_WIDTH] : {ID_WIDTH{1'b0}};
328	wire [DEST_WIDTH-1:0]  m_axis_tdest_pipe  = DEST_ENABLE ? m_axis[DEST_OFFSET +: DEST_WIDTH] : {DEST_WIDTH{1'b0}};
329	wire [USER_WIDTH-1:0]  m_axis_tuser_pipe  = USER_ENABLE ? (m_terminate_frame_reg ? USER_BAD_FRAME_VALUE : m_axis[USER_OFFSET +: USER_WIDTH]) : {USER_WIDTH{1'b0}};
330	
331	wire                   m_axis_tready_out;
332	wire                   m_axis_tvalid_out;
333	
334	wire [DATA_WIDTH-1:0]  m_axis_tdata_out;
335	wire [KEEP_WIDTH-1:0]  m_axis_tkeep_out;
336	wire                   m_axis_tlast_out;
337	wire [ID_WIDTH-1:0]    m_axis_tid_out;
338	wire [DEST_WIDTH-1:0]  m_axis_tdest_out;
339	wire [USER_WIDTH-1:0]  m_axis_tuser_out;
340	
341	wire pipe_ready;
342	
343	assign s_status_depth = (KEEP_ENABLE && KEEP_WIDTH > 1) ? {s_depth_reg, {$clog2(KEEP_WIDTH){1'b0}}} : s_depth_reg;
344	assign s_status_depth_commit = (KEEP_ENABLE && KEEP_WIDTH > 1) ? {s_depth_commit_reg, {$clog2(KEEP_WIDTH){1'b0}}} : s_depth_commit_reg;
345	assign s_status_overflow = overflow_reg;
346	assign s_status_bad_frame = bad_frame_reg;
347	assign s_status_good_frame = good_frame_reg;
348	
349	assign m_status_depth = (KEEP_ENABLE && KEEP_WIDTH > 1) ? {m_depth_reg, {$clog2(KEEP_WIDTH){1'b0}}} : m_depth_reg;
350	assign m_status_depth_commit = (KEEP_ENABLE && KEEP_WIDTH > 1) ? {m_depth_commit_reg, {$clog2(KEEP_WIDTH){1'b0}}} : m_depth_commit_reg;
351	assign m_status_overflow = overflow_sync3_reg ^ overflow_sync4_reg;
352	assign m_status_bad_frame = bad_frame_sync3_reg ^ bad_frame_sync4_reg;
353	assign m_status_good_frame = good_frame_sync3_reg ^ good_frame_sync4_reg;
354	
355	// reset synchronization
356	always @(posedge m_clk or posedge m_rst) begin
357	    if (m_rst) begin
358	        s_rst_sync1_reg <= 1'b1;
359	    end else begin
360	        s_rst_sync1_reg <= 1'b0;
361	    end
362	end
363	
364	always @(posedge s_clk) begin
365	    s_rst_sync2_reg <= s_rst_sync1_reg;
366	    s_rst_sync3_reg <= s_rst_sync2_reg;
367	end
368	
369	always @(posedge s_clk or posedge s_rst) begin
370	    if (s_rst) begin
371	        m_rst_sync1_reg <= 1'b1;
372	    end else begin
373	        m_rst_sync1_reg <= 1'b0;
374	    end
375	end
376	
377	always @(posedge m_clk) begin
378	    m_rst_sync2_reg <= m_rst_sync1_reg;
379	    m_rst_sync3_reg <= m_rst_sync2_reg;
380	end
381	
382	// Write logic
383	always @(posedge s_clk) begin
384	    overflow_reg <= 1'b0;
385	    bad_frame_reg <= 1'b0;
386	    good_frame_reg <= 1'b0;
387	
388	    if (FRAME_FIFO && wr_ptr_update_valid_reg) begin
389	        // have updated pointer to sync
390	        if (wr_ptr_update_reg == wr_ptr_update_ack_sync2_reg) begin
391	            // no sync in progress; sync update
392	            wr_ptr_update_valid_reg <= 1'b0;
393	            wr_ptr_sync_commit_reg <= wr_ptr_commit_reg;
394	            wr_ptr_update_reg <= !wr_ptr_update_ack_sync2_reg;
395	        end
396	    end
397	
