846	        s_pause_ack_sync1_reg <= pause_reg;
847	    end
848	
849	    assign m_axis_tready_out = m_axis_tready && !pause_reg;
850	    assign m_axis_tvalid = m_axis_tvalid_out && !pause_reg;
851	
852	    assign m_axis_tdata = m_axis_tdata_out;
853	    assign m_axis_tkeep = m_axis_tkeep_out;
854	    assign m_axis_tlast = m_axis_tlast_out;
855	    assign m_axis_tid   = m_axis_tid_out;
856	    assign m_axis_tdest = m_axis_tdest_out;
857	    assign m_axis_tuser = m_axis_tuser_out;
858	
859	    assign s_pause_ack = s_pause_ack_sync3_reg;
860	    assign m_pause_ack = pause_reg;
861	
862	    always @(posedge m_clk) begin
863	        if (FRAME_PAUSE) begin
864	            if (pause_reg) begin
865	                // paused; update pause status
866	                pause_reg <= m_pause_req || s_pause_req_sync3_reg;
867	            end else if (m_axis_tvalid_out) begin
868	                // frame transfer; set frame bit
869	                pause_frame_reg <= 1'b1;
870	                if (m_axis_tready && m_axis_tlast) begin
871	                    // end of frame; clear frame bit and update pause status
872	                    pause_frame_reg <= 1'b0;
873	                    pause_reg <= m_pause_req || s_pause_req_sync3_reg;
874	                end
875	            end else if (!pause_frame_reg) begin
876	                // idle; update pause status
877	                pause_reg <= m_pause_req || s_pause_req_sync3_reg;
878	            end
879	        end else begin
880	            pause_reg <= m_pause_req || s_pause_req_sync3_reg;
881	        end
882	
883	        if (m_rst) begin
884	            pause_frame_reg <= 1'b0;
885	            pause_reg <= 1'b0;
886	        end
887	    end
888	
889	end else begin
890	
891	    assign m_axis_tready_out = m_axis_tready;
892	    assign m_axis_tvalid = m_axis_tvalid_out;
893	
894	    assign m_axis_tdata = m_axis_tdata_out;
895	    assign m_axis_tkeep = m_axis_tkeep_out;
896	    assign m_axis_tlast = m_axis_tlast_out;
897	    assign m_axis_tid   = m_axis_tid_out;
898	    assign m_axis_tdest = m_axis_tdest_out;
899	    assign m_axis_tuser = m_axis_tuser_out;
900	
901	    assign s_pause_ack = 1'b0;
902	    assign m_pause_ack = 1'b0;
903	
904	end
905	
906	endgenerate
907	
908	endmodule
909	
910	`resetall
911

